<script setup lang="ts">
import { cloneRecordItems } from '../../shared/record-payload'
type Row = Record<string, any>
type Page = 'dashboard' | 'records' | 'reports'
const page = ref<Page>('dashboard'), user = ref<any>(null), auth = ref<'setup' | 'login' | 'recover'>('login'), busy = ref(false), error = ref(''), notice = ref('')
const rows = ref<Row[]>([]), statuses = ref<Row[]>([]), dashboard = ref<any>(null), search = ref(''), recordFilter = ref(''), activityDays = ref(30)
const modal = ref(false), editId = ref<number | null>(null), report = ref<any>(null), reportType = ref('monthly'), reportDay = ref(new Date().toISOString().slice(0, 10)), reportMonth = ref(new Date().toISOString().slice(0, 7)), reportDays = ref(7)
const credentials = reactive({ username: '', displayName: '', password: '', recoveryKey: '', newPassword: '' })
const password = computed({ get: () => auth.value === 'recover' ? credentials.newPassword : credentials.password, set: value => { if (auth.value === 'recover') credentials.newPassword = value; else credentials.password = value } })
const empty = () => ({ recordDate: new Date().toISOString().slice(0, 10), recordNumber: '', clientName: '', contacts: '', location: '', sourceOfInfo: '', eventDate: '', proformaNo: '', invoiceNo: '', orderFormNo: '', deliveryFormNo: '', statusId: 0, taxRateBasisPoints: 0, notes: '', items: [{ description: '', quantity: 1, unitPrice: 0 }] })
const form = reactive(empty())
const subtotal = computed(() => form.items.reduce((sum, item) => sum + Math.round(Number(item.quantity || 0) * Number(item.unitPrice || 0)), 0))
const total = computed(() => subtotal.value + Math.round(subtotal.value * Number(form.taxRateBasisPoints || 0) / 10000))
const isPaid = computed(() => Boolean((form as any).paidAt))
const money = (n?: number) => new Intl.NumberFormat('en-TZ', { style: 'currency', currency: 'TZS', maximumFractionDigits: 0 }).format(Number(n || 0))
const date = (value?: string) => value ? new Date(`${value}T00:00:00`).toLocaleDateString('en-GB') : '—'
const fail = (message?: string) => error.value = message || 'Something went wrong. Please try again.'
async function load() { const [a, b, c] = await Promise.all([window.api!.statuses.list(), window.api!.records.list({ search: search.value, filter: recordFilter.value }), window.api!.dashboard.data({ days: activityDays.value })]); if (!a.ok || !b.ok || !c.ok) return fail('Could not load the workspace.'); statuses.value = a.data as Row[]; rows.value = b.data as Row[]; dashboard.value = c.data }
async function boot() { const r: any = await window.api?.auth.status(); if (!r?.ok) return fail(r?.error?.message); user.value = r.data.user; auth.value = r.data.hasUser ? 'login' : 'setup'; if (user.value) await load() }
async function signIn() { busy.value = true; error.value = ''; try { let r: any; if (auth.value === 'setup') r = await window.api!.auth.setup({ username: credentials.username, displayName: credentials.displayName, password: credentials.password }); else if (auth.value === 'recover') r = await window.api!.auth.recover({ username: credentials.username, recoveryKey: credentials.recoveryKey, newPassword: credentials.newPassword }); else r = await window.api!.auth.login({ username: credentials.username, password: credentials.password }); if (!r.ok) return fail(r.error.message); if (auth.value === 'recover') { notice.value = `Password reset. New recovery key: ${r.data.recoveryKey}`; auth.value = 'login'; return } user.value = auth.value === 'setup' ? r.data.user : r.data; if (auth.value === 'setup') notice.value = `Save this recovery key: ${r.data.recoveryKey}`; await load() } finally { busy.value = false } }
async function logout() { await window.api?.auth.logout(); user.value = null; auth.value = 'login' }
function newRecord() { Object.assign(form, empty()); editId.value = null; modal.value = true }
async function edit(row: Row) { const r: any = await window.api!.records.get(row.id); if (!r.ok || !r.data) return fail(r.error?.message); const x = r.data.record; Object.assign(form, { recordDate: x.record_date, recordNumber: x.record_number || '', clientName: x.client_name, contacts: x.contacts || '', location: x.location || '', sourceOfInfo: x.source_of_info || '', eventDate: x.event_date || '', proformaNo: x.proforma_no || '', invoiceNo: x.invoice_no || '', orderFormNo: x.order_form_no || '', deliveryFormNo: x.delivery_form_no || '', statusId: x.status_id, taxRateBasisPoints: x.tax_rate_bp, notes: x.notes || '', items: r.data.items.map((i: any) => ({ description: i.description, quantity: i.quantity_x100 / 100, unitPrice: i.unit_price_minor })), paidAt: x.paid_at }); editId.value = row.id; modal.value = true }
async function save() { busy.value = true; error.value = ''; try { const record = { ...form, paidAt: undefined, items: undefined, currency: 'TZS' }; const r: any = editId.value === null ? await window.api!.records.create({ record, items: cloneRecordItems(form.items) }) : await window.api!.records.update({ id: editId.value, record, items: cloneRecordItems(form.items) }); if (!r.ok) return fail(r.error.message); modal.value = false; notice.value = 'Record saved.'; await load() } finally { busy.value = false } }
async function workflow(row: Row, stage: 'confirmed' | 'paid' | 'delivered') { const r: any = await window.api!.records.workflow({ id: row.id, stage, enabled: !row[`${stage}_at`] }); if (!r.ok) return fail(r.error.message); await load() }
async function openFiltered(filter = '') { recordFilter.value = filter; page.value = 'records'; await load() }
async function previewReport() { const params = reportType.value === 'daily' ? { day: reportDay.value } : reportType.value === 'monthly' ? { month: reportMonth.value } : { days: reportDays.value }; const r: any = await window.api!.reports!.data(reportType.value, params); if (!r.ok) return fail(r.error.message); report.value = r.data }
async function exportExcel() { if (report.value) { const r: any = await window.api!.reports!.exportExcel(report.value); if (!r.ok) fail(r.error.message) } }
async function exportPdf() { if (report.value) { const r: any = await window.api!.reports!.exportPdf(report.value); if (!r.ok) fail(r.error.message) } }
onMounted(boot)
</script>

<template>
  <main v-if="user" class="app"><aside><div class="brand">BR <strong>BUSINESS RECORDS</strong></div><nav><button :class="{active:page==='dashboard'}" @click="page='dashboard'">Overview</button><button :class="{active:page==='records'}" @click="openFiltered()">Records</button><button :class="{active:page==='reports'}" @click="page='reports'">Reports</button></nav><button @click="logout">Sign out</button></aside><section class="content"><header><div><small>{{ page === 'dashboard' ? 'EXECUTIVE OVERVIEW' : page === 'records' ? 'RECORD MANAGEMENT' : 'REPORTING' }}</small><h1>{{ page === 'dashboard' ? `Good day, ${user.displayName}` : page === 'records' ? 'Business records' : 'Reports' }}</h1></div><button v-if="page!=='reports'" class="primary" @click="newRecord">+ New record</button></header><p v-if="notice" class="notice">{{ notice }}</p><p v-if="error" class="error">{{ error }}</p>
    <template v-if="page==='dashboard'"><section class="metrics"><button class="metric"><small>MONTHLY VALUE</small><b>{{ money(dashboard?.monthSummary?.[0]?.total) }}</b></button><button class="metric" @click="openFiltered()"><small>RECORDS TODAY</small><b>{{ dashboard?.recordsToday || 0 }}</b></button><button class="metric" @click="openFiltered()"><small>ACTIVE RECORDS</small><b>{{ dashboard?.activeRecords || 0 }}</b></button><button class="metric" @click="openFiltered()"><small>UPCOMING EVENTS</small><b>{{ dashboard?.upcomingEvents?.length || 0 }}</b></button><button class="metric alert" @click="openFiltered('unpaid')"><small>UNPAID INVOICES</small><b>{{ dashboard?.unpaidCount || 0 }}</b></button><button class="metric info" @click="openFiltered('delivery')"><small>NEEDS DELIVERY</small><b>{{ dashboard?.deliveryCount || 0 }}</b></button></section><section class="grid"><article class="card"><div class="heading"><div><h2>Event activity</h2><small>Confirmed and paid event value</small></div><div class="ranges"><button v-for="days in [7,30,90]" :key="days" :class="{selected:activityDays===days}" @click="activityDays=days;load()">{{ days }}d</button></div></div><div v-if="dashboard?.eventActivity?.length" class="chart">{{ dashboard.eventActivity.map((point:any)=>`${date(point.event_date)} ${money(point.total)}`).join(' · ') }}</div><p v-else class="empty">No paid event activity in this period.</p></article><article class="card"><h2>Record status</h2><button v-for="s in dashboard?.byStatus || []" :key="s.name" class="status" @click="openFiltered(`status:${s.name}`)"><span><i :style="{background:s.color}"></i>{{ s.name }}</span><b>{{ s.count }}</b></button></article></section></template>
    <template v-else-if="page==='records'"><div class="toolbar"><input v-model="search" placeholder="Search client, record or invoice" @input="load"><button v-if="recordFilter" @click="openFiltered()">Clear filter</button><span>{{ rows.length }} records</span></div><article class="card table"><table><thead><tr><th>RECORD</th><th>CLIENT</th><th>EVENT DATE</th><th>STATUS</th><th>TOTAL</th><th>WORKFLOW</th><th></th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{ r.record_number || '—' }}</td><td><b>{{ r.client_name }}</b><small>{{ r.contacts || 'No contact details' }}</small></td><td>{{ date(r.event_date) }}</td><td>{{ r.status_name }}</td><td>{{ money(r.grand_total_minor) }}</td><td class="workflow"><button :class="{done:r.confirmed_at}" @click="workflow(r,'confirmed')">Confirmed</button><button :class="{done:r.paid_at}" :disabled="!r.confirmed_at" @click="workflow(r,'paid')">Paid</button><button :class="{done:r.delivered_at}" :disabled="!r.paid_at" @click="workflow(r,'delivered')">Delivered</button></td><td><button @click="edit(r)">Edit</button></td></tr></tbody></table><p v-if="!rows.length" class="empty">No matching records.</p></article></template>
    <template v-else><article class="card controls"><label>Report<select v-model="reportType"><option value="daily">Daily report</option><option value="monthly">Monthly report</option><option value="upcoming-events">Upcoming events</option><option value="unpaid-invoices">Unpaid invoices</option><option value="delivery-due">Delivery due</option><option value="status-summary">Status summary</option><option value="client-summary">Client summary</option></select></label><label v-if="reportType==='daily'">Date<input v-model="reportDay" type="date"></label><label v-if="reportType==='monthly'">Month<input v-model="reportMonth" type="month"></label><label v-if="reportType==='upcoming-events'">Days ahead<input v-model.number="reportDays" type="number" min="1" max="365"></label><button class="primary" @click="previewReport">Preview</button></article><article v-if="report" class="card"><div class="heading"><div><h2>{{ report.title }}</h2><small>{{ report.period }}</small></div><div><button @click="exportExcel">Export Excel</button><button class="primary" @click="exportPdf">Save PDF</button></div></div><div class="summary" v-if="report.summary?.length"><span v-for="s in report.summary" :key="JSON.stringify(s)">{{ s.records || 'Total' }} records · {{ money(s.total_minor ?? s.grand_total_minor) }}</span></div><div class="table"><table><thead><tr><th v-for="(_,key) in report.rows[0] || {}" :key="String(key)">{{ String(key).replaceAll('_',' ') }}</th></tr></thead><tbody><tr v-for="(row,index) in report.rows" :key="index"><td v-for="(value,key) in row" :key="String(key)">{{ value }}</td></tr></tbody></table></div></article></template>
  </section></main>
  <main v-else class="auth"><form @submit.prevent="signIn"><small>{{ auth==='setup'?'WELCOME':'WELCOME BACK' }}</small><h1>{{ auth==='setup'?'Create your workspace':auth==='recover'?'Reset password':'Sign in' }}</h1><label v-if="auth==='setup'">Your name<input v-model="credentials.displayName" required></label><label>Username<input v-model="credentials.username" required></label><label v-if="auth==='recover'">Recovery key<input v-model="credentials.recoveryKey" required></label><label>{{ auth==='recover'?'New password':'Password' }}<input v-model="password" type="password" minlength="6" required></label><p v-if="error" class="error">{{ error }}</p><button class="primary" :disabled="busy">{{ busy?'Please wait…':auth==='setup'?'Create workspace':auth==='recover'?'Reset password':'Sign in' }}</button><button v-if="auth==='login'" type="button" @click="auth='recover'">Forgot password?</button><button v-else type="button" @click="auth='login'">Back to sign in</button></form></main>
  <div v-if="modal" class="shade"><form class="modal" @submit.prevent="save"><header><h2>{{ editId===null?'New record':'Edit record' }}</h2><button type="button" @click="modal=false">×</button></header><p v-if="isPaid" class="notice">Paid records are locked. Clear Paid before changing commercial details.</p><fieldset :disabled="isPaid"><label>Record date<input v-model="form.recordDate" type="date" required></label><label>Client<input v-model="form.clientName" required></label><label>Event date<input v-model="form.eventDate" type="date"></label><label>Invoice number<input v-model="form.invoiceNo"></label><label>Status<select v-model.number="form.statusId"><option v-for="s in statuses" :value="s.id" :key="s.id">{{ s.name }}</option></select></label><label>Tax (%)<input v-model.number="form.taxRateBasisPoints" type="number" min="0"></label><div v-for="(item,index) in form.items" :key="index" class="item"><input v-model="item.description" placeholder="Item" required><input v-model.number="item.quantity" type="number" min="1"><input v-model.number="item.unitPrice" type="number" min="0"></div></fieldset><footer><b>Total: {{ money(total) }}</b><button type="button" @click="modal=false">Cancel</button><button class="primary" :disabled="busy">Save record</button></footer></form></div>
</template>

<style scoped>
:global(*){box-sizing:border-box}:global(body){margin:0;background:#f4f7fb;color:#17253b;font:14px Inter,system-ui,sans-serif}.app{display:flex;min-height:100vh}aside{width:230px;padding:24px 14px;background:#102038;color:#d5deeb;display:flex;flex-direction:column;gap:34px}.brand{font-weight:900;color:white;display:flex;gap:9px;align-items:center}.brand:first-letter{background:#5ce0a1;color:#102038;padding:9px;border-radius:8px}nav{display:grid;gap:6px}button{border:0;background:transparent;cursor:pointer;font:inherit;color:inherit;padding:9px;border-radius:7px;text-align:left}aside button.active,aside button:hover{background:#273a55;color:#fff}aside>button:last-child{margin-top:auto}.content{flex:1;max-width:1600px;padding:30px 40px;margin:auto;width:100%}header,.heading,.toolbar,.controls,footer{display:flex;justify-content:space-between;gap:12px;align-items:center}h1,h2{margin:4px 0}h1{font-size:29px}h2{font-size:17px}small{color:#718198}.primary{background:#147d58;color:white;font-weight:800;padding:10px 14px}.notice,.error{padding:11px 14px;border-radius:8px}.notice{background:#e1f5e9;color:#126244}.error{background:#fff0ef;color:#a62d28}.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin:22px 0}.metric,.card{background:white;border:1px solid #dfe7ef;border-radius:11px}.metric{padding:17px;text-align:left}.metric b{font-size:22px;display:block;margin-top:8px}.metric.alert{background:#fff5e8}.metric.info{background:#eaf6f7}.grid{display:grid;grid-template-columns:2fr 1fr;gap:16px}.card{padding:19px}.ranges button.selected,.workflow .done{background:#147d58;color:#fff}.chart{margin-top:22px;padding:20px;background:#edf8f2;line-height:2}.status{display:flex;width:100%;justify-content:space-between;border-bottom:1px solid #edf1f5}.status i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:7px}.toolbar{margin-bottom:14px}.toolbar input,.controls input,.controls select,fieldset input,fieldset select{padding:10px;border:1px solid #d5e0e9;border-radius:7px;font:inherit}.toolbar input{width:360px}.table{overflow:auto;padding:0}table{width:100%;border-collapse:collapse}th,td{padding:12px;text-align:left;border-bottom:1px solid #edf1f5;white-space:nowrap}th{text-transform:uppercase;font-size:10px;color:#728198;background:#fafbfd}.workflow{display:flex;gap:4px}.workflow button{border:1px solid #cfd9e3;padding:5px;font-size:11px}.workflow button:disabled{opacity:.45}.summary{display:flex;gap:10px;margin:16px 0}.summary span{background:#edf8f2;padding:9px;border-radius:6px}.auth{min-height:100vh;display:grid;place-items:center;background:#102038}.auth form,.modal{background:white;padding:28px;border-radius:12px;width:min(560px,94vw);display:grid;gap:13px}.auth label,fieldset label{display:grid;gap:5px;font-weight:700}.auth input{padding:10px;border:1px solid #d5e0e9;border-radius:7px}.shade{position:fixed;inset:0;background:#102038bb;display:grid;place-items:center;z-index:5}.modal header{padding-bottom:12px;border-bottom:1px solid #e4eaf0}.modal fieldset{display:grid;grid-template-columns:repeat(2,1fr);gap:11px;border:0;padding:0}.item{display:grid;grid-template-columns:2fr 1fr 1fr;gap:7px;grid-column:span 2}.empty{text-align:center;color:#728198}@media(max-width:1000px){.metrics{grid-template-columns:repeat(3,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:700px){aside{width:65px}.brand strong,aside button{font-size:0}.content{padding:20px 12px}.metrics{grid-template-columns:repeat(2,1fr)}.modal fieldset{grid-template-columns:1fr}.item{grid-column:span 1}}
</style>
